import type { FilterDataStructure } from 'models/Filters';

/**
 * Dev mock aligned with WatchTower Integration:
 */
export const watchTowerFilterPreset: FilterDataStructure = {
  kpis: {
    default: { value: 'volume', label: 'Volume', full: 'Volume' },
    values: [
      { value: 'volume', label: 'Volume', full: 'Volume' },
      { value: 'nr', label: 'Net Revenue', full: 'Net Revenue' },
    ],
    enabled: true,
  },
  zones: {
    default: { value: 'SAZ', label: 'SAZ' },
    values: [
      { value: 'AFR', label: 'AFR', isDisabled: true },
      { value: 'APAC', label: 'APAC', isDisabled: true },
      { value: 'EUR', label: 'EUR', isDisabled: true },
      { value: 'NAZ', label: 'NAZ', isDisabled: true },
      { value: 'MAZ', label: 'MAZ', isDisabled: true },
      { value: 'SAZ', label: 'SAZ' },
    ],
    enabled: true,
  },
  country: {
    default: { value: 'BRA', label: 'Brazil' },
    values: {
      SAZ: [
        { value: 'BRA', label: 'Brazil' },
        { value: 'ARG', label: 'Argentina' },
        { value: 'CHL', label: 'Chile' },
      ],
    },
    enabled: true,
  },
  region: {
    default: undefined,
    values: {
      BRA: [
        { value: 'SP', label: 'Sao Paulo' },
        { value: 'RJ', label: 'Rio de Janeiro' },
        { value: 'MG', label: 'Minas Gerais' },
      ],
      ARG: [
        { value: 'BA', label: 'Buenos Aires' },
        { value: 'CBA', label: 'Cordoba' },
      ],
      CHL: [{ value: 'RM', label: 'Region Metropolitana' }],
    },
    enabled: true,
  },
  watch_tower_brands: {
    default: null,
    values: {
      BRA: {
        default: null,
        brands: [
          { value: 'BRAHMA', label: 'Brahma' },
          { value: 'SKOL', label: 'Skol' },
          { value: 'STELLA', label: 'Stella Artois' },
        ],
      },
      ARG: {
        default: null,
        brands: [
          { value: 'BRAHMA', label: 'Brahma' },
          { value: 'CORONA', label: 'Corona' },
        ],
      },
      CHL: {
        default: null,
        brands: [
          { value: 'CORONA', label: 'Corona' },
          { value: 'STELLA', label: 'Stella Artois' },
        ],
      },
    },
    enabled: true,
  },
  driver: {
    default: null,
    values: [
      { value: 'sales_marketing', label: 'Sales and Marketing' },
      { value: 'execution', label: 'Execution' },
    ],
    enabled: true,
  },
  vehicle_level_1: {
    default: null,
    values: [
      { value: 'marketing', label: 'Marketing' },
      { value: 'distribution', label: 'Distribution' },
      { value: 'weighted_dist', label: 'Weighted Distribution' },
    ],
    enabled: true,
  },
  vehicle_level_2: {
    default: null,
    values: [
      { value: 'media', label: 'Media' },
      { value: 'trade', label: 'Trade' },
      { value: 'perfect_store', label: 'Perfect Store' },
    ],
    enabled: true,
  },
  vehicle_level_3: {
    default: null,
    values: [
      { value: 'digital', label: 'Digital' },
      { value: 'traditional', label: 'Traditional' },
    ],
    enabled: true,
  },
  vehicle_level_4: {
    default: null,
    values: [
      { value: 'social', label: 'Social' },
      { value: 'display', label: 'Display' },
    ],
    enabled: true,
  },
  vehicle_level_5: {
    default: null,
    values: [
      { value: 'tiktok', label: 'Tiktok' },
      { value: 'instagram', label: 'Instagram' },
    ],
    enabled: true,
  },
  channel: {
    default: null,
    values: [
      { value: 'on_trade', label: 'On Trade' },
      { value: 'off_trade', label: 'Off Trade' },
      { value: 'key_account', label: 'Key Account' },
