  periods: {
    default: { value: 'YTD', label: "YTD Jun'26" },
    values: [
      { value: 'YTD', label: "YTD Jun'26", full: 'Year to Date (YTD)' },
      { value: 'MTD', label: "Jun'26", full: 'Month to Date (MTD)' },
    ],
    enabled: true,
  },
  currency: {
    default: { value: 'lcu', label: 'LCU (R$)' },
    values: [
      { value: 'lcu', label: 'LCU (R$)' },
      { value: 'usd', label: 'USD ($)' },
    ],
    enabled: true,
  },
};
